#include <HBEngine/SceneRender.hpp>
#include <nlohmann/json.hpp>
#include <cassert>
#include <fstream>
#include <iostream>
using namespace hb::gpu;
static std::vector<std::uint8_t> decode(const std::string& text){const std::string chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";std::vector<std::uint8_t> out;unsigned value=0,bits=0;for(char c:text){if(c=='=')break;const auto at=chars.find(c);if(at==std::string::npos)throw std::runtime_error("base64");value=(value<<6)|static_cast<unsigned>(at);bits+=6;if(bits>=8){bits-=8;out.push_back(static_cast<std::uint8_t>(value>>bits));}}return out;}
template<class F>static void rejects(F fn){bool rejected=false;try{fn();}catch(const std::exception&){rejected=true;}assert(rejected);}
int main(int argc,char** argv){
 assert(argc==2);std::ifstream file(argv[1]);nlohmann::json cases;file>>cases;Device gpu;SceneRenderer renderer(gpu,16,16);auto mesh=renderer.createMesh({{{-1,-1,.4f}},{{1,-1,.4f}},{{1,1,.4f}},{{-1,1,.4f}}},{0,1,2,0,2,3});SceneMaterial material;material.unlit=true;material.toneMapped=false;material.doubleSided=true;SceneFrame frame;frame.ambient={0,0,0,1};nlohmann::json rows=nlohmann::json::array();
 for(const auto& test:cases){const auto& packet=test.at("packet");const bool volume=test.at("kind")=="volumetexture",cube=test.at("kind")=="cubemap",flat=test.at("kind")=="texture2d";const std::uint32_t width=packet.at("width"),height=packet.at("height"),depth=packet.at("layers");const auto base=decode(packet.at("rgbaBase64"));std::vector<SceneRenderer::TextureMipLevel> levels;std::uint64_t expectedBytes=base.size();for(const auto& mip:packet.at("mipLevels")){levels.push_back({mip.at("width"),mip.at("height"),decode(mip.at("rgbaBase64")),mip.value("layers",1u)});expectedBytes+=levels.back().rgba.size();}
  auto create=[&](const std::vector<SceneRenderer::TextureMipLevel>& mips,bool automatic=false){return renderer.createDataTexture(width,height,base,4,false,depth,false,!volume&&!cube&&!flat,cube?"cube":volume?"volume":"2d",automatic,false,mips);};auto texture=create(levels);assert(texture.storageBytes()==expectedBytes);
  for(std::size_t lod=0;lod<test.at("colors").size();++lod)for(std::size_t layer=0;layer<test.at("colors")[lod].size();++layer){const auto count=test.at("colors")[lod].size();static const char* directions[6]={"float3(1,0,0)","float3(-1,0,0)","float3(0,1,0)","float3(0,-1,0)","float3(0,0,1)","float3(0,0,-1)"};const std::string coordinate=flat?"float2(.5,.5)":cube?directions[layer]:"float3(.5,.5,"+(volume?std::to_string((static_cast<double>(layer)+.5)/count):std::to_string(layer))+")",expression="tex.SampleLevel(samp,"+coordinate+","+std::to_string(lod)+")";auto program=renderer.createProgram(std::string(flat?"Texture2D":cube?"TextureCube":volume?"Texture3D":"Texture2DArray")+" tex:register(t8);SamplerState samp:register(s0);","base="+expression+";",{});renderer.begin(frame);renderer.draw(mesh,identity,identity,material,{}, {},0,0,&program,{&texture},{0});const auto pixels=renderer.readPixels();const auto at=(8*16+8)*4;std::array<int,4> rgba{};for(int c=0;c<4;c++){rgba[c]=pixels[at+c];const int authored=test.at("colors")[lod][layer][c].get<int>();const double linear=authored/255.0;const int expected=c==3?authored:static_cast<int>(std::lround(255.0*(linear<=.0031308?linear*12.92:1.055*std::pow(linear,1.0/2.4)-.055)));if(std::abs(rgba[c]-expected)>=3){std::cerr<<nlohmann::json{{"kind",test.at("kind")},{"lod",lod},{"layer",layer},{"channel",c},{"actual",rgba[c]},{"expected",expected},{"authoredLinearByte",authored}};return 2;}}rows.push_back({{"kind",test.at("kind")},{"lod",lod},{"layer",layer},{"rgba",rgba}});}
  auto wrong=levels;wrong[0].layers++;rejects([&]{create(wrong);});wrong=levels;wrong[0].width++;rejects([&]{create(wrong);});wrong=levels;wrong[0].rgba.pop_back();rejects([&]{create(wrong);});wrong=levels;wrong.push_back(levels.back());rejects([&]{create(wrong);});rejects([&]{create(levels,true);});
 }
 std::cout<<nlohmann::json{{"passed",true},{"actualD3D11",true},{"rows",rows},{"invalidChainsRejected",cases.size()*5}};
}
